mapper.select:
SELECT fuel_test_bill_no AS fuelTestBillNo, fuel_date AS fuelDate, fuel_name AS fuelName, fuel_temp AS fuelTemp,fuel_dnst AS fuelDnst, fuel_airport_code AS fuelAirportCode ,fuel_staff_name AS fuelStaffName, fuel_logic_del_flg AS fuelLogicDelFlg, fuel_pub_type AS fuelPubType, fuel_type AS fuelType FROM T_FUEL WHERE DATE_FORMAT(fuel_date,'%Y-%m-%d') IN (CURDATE(),DATE_SUB(CURDATE(), INTERVAL 1 DAY),DATE_SUB(CURDATE(),INTERVAL 2 DAY), DATE_SUB(CURDATE(), INTERVAL 3 DAY),DATE_SUB(CURDATE(), INTERVAL 4 DAY), DATE_SUB(CURDATE(), INTERVAL 5 DAY),DATE_SUB(CURDATE(), INTERVAL 6 DAY),DATE_SUB(CURDATE(),interval 7 day))
AND fuel_airport_code=#{staffAirportCode}
-- and fuel_logic_del_flg = 0 ORDER BY fuel_date DESC

mapper.insert:
INSERT into T_FUEL( fuel_test_bill_no, fuel_date, fuel_name, fuel_temp, fuel_dnst, fuel_airport_code
                  , fuel_staff_name, fuel_logic_del_flg)
values ( #{fuel.fuelTestBillNo}, NOW(), #{fuel.fuelName}, #{fuel.fuelTemp}, #{fuel.fuelDnst}
       , #{fuel.fuelAirportCode}
       , #{staffName}, 0)

mapper.update:
